#!/usr/bin/env python3
import csv, json
from collections import Counter
from datetime import datetime, timezone, timedelta
from zoneinfo import ZoneInfo

READINGS = 'readings.csv'
TZ = ZoneInfo('America/Los_Angeles')
ROLLOVER = 1_000_000.0

rows = []
with open(READINGS, newline='') as f:
    for row in csv.DictReader(f):
        rows.append({
            'meter_id': row['meter_id'],
            'ts': datetime.fromisoformat(row['ts']).replace(tzinfo=timezone.utc),
            'register_kwh': float(row['register_kwh']),
        })

flags = []
# Basic validations.
if len({r['meter_id'] for r in rows}) != 1:
    flags.append('multiple_meters')
if rows != sorted(rows, key=lambda r: r['ts']):
    flags.append('unsorted_readings')
rows = sorted(rows, key=lambda r: r['ts'])
counts = Counter(r['ts'] for r in rows)
if any(c > 1 for c in counts.values()):
    flags.append('duplicate_timestamps')
for a, b in zip(rows, rows[1:]):
    if b['ts'] - a['ts'] != timedelta(hours=1):
        flags.append('missing_or_irregular_hourly_readings')
        break

start_utc = datetime(2026, 11, 1, 0, 0, tzinfo=TZ).astimezone(timezone.utc)
end_utc = datetime(2026, 12, 1, 0, 0, tzinfo=TZ).astimezone(timezone.utc)
cutover_utc = datetime(2026, 11, 13, 10, 0, tzinfo=TZ).astimezone(timezone.utc)

by_ts = {r['ts']: r for r in rows}
if start_utc not in by_ts or end_utc not in by_ts:
    flags.append('missing_month_boundary_reading')

# Sum interval deltas for intervals (previous_ts, ts] within the local-calendar month.
# Register rolls over at 1,000,000.0 kWh. Maintenance log says after 2026-11-13
# 10:00 local, displayed energy is 1/10 true energy, so multiply interval deltas
# after that boundary by 10.
total = 0.0
rollovers = 0
for prev, cur in zip(rows, rows[1:]):
    prev_ts = prev['ts']
    ts = cur['ts']
    if not (start_utc < ts <= end_utc):
        continue
    delta = cur['register_kwh'] - prev['register_kwh']
    if delta < 0:
        delta += ROLLOVER
        rollovers += 1
    # Since the CT replacement time is exactly an hourly reading boundary,
    # intervals with prev_ts >= cutover_utc are fully after the change.
    if prev_ts >= cutover_utc:
        delta *= 10.0
    total += delta

if rollovers:
    flags.append('register_rollover')
flags.append('ct_ratio_change_corrected')

# If there are validation flags that make the result doubtful, emit cannot_determine.
fatal = {'multiple_meters', 'duplicate_timestamps', 'missing_or_irregular_hourly_readings', 'missing_month_boundary_reading', 'unsorted_readings'}
if fatal.intersection(flags):
    result = {'status': 'cannot_determine', 'reason': 'data validation failed', 'flags': flags}
else:
    result = {'answer': round(total, 1), 'flags': flags}

